<script setup>
import ReportStamp from './ReportStamp.vue';
// Desktop composition adapted from MDS DashboardPage/ListPage/FormPage templates.
import {s,canEdit,canAdmin,isSuper,title,nav,run,navigate,selectEvent,showEventList,roleNames,dateText,number,reports,exportExcel,exportPng,insights,saveEvent,loadRows,editRow,setRole} from './store';
import {currentHeaderMode,sidebarCollapsed} from './mds/theme-state';
import ReportFilters from './ReportFilters.vue';import ChartPanel from './ChartPanel.vue';import KpiCard from './KpiCard.vue';import TargetsPanel from './TargetsPanel.vue';import ImportFields from './ImportFields.vue';import SettingsFields from './SettingsFields.vue';import MemberImport from './MemberImport.vue';
const memberColumns=[{key:'name',label:'Họ và tên'},{key:'email',label:'Email'},{key:'role',label:'Quyền'},{key:'actions',label:'Thao tác'}];
const rowColumns=[{key:'name',label:'Họ và tên'},{key:'company',label:'Công ty'},{key:'position',label:'Chức vụ'},{key:'submitted_at',label:'Thời gian submit'},{key:'attendance_mode',label:'Hình thức'},{key:'actions',label:'Thao tác'}];
</script><template><div class="relative flex h-full flex-col overflow-hidden">
<MHeaderBar class="shrink-0" app-name="MISA Event Report" :variant="currentHeaderMode" :user="s.user" :show-assistant="false" :show-chat="false" :show-notifications="false" :show-help="false" :show-more="false" :show-whats-new="false" search-placeholder="Tìm sự kiện (Enter)" @settings="s.appearance=true" @user-click="s.dialog='account'" @app-switcher="run(()=>showEventList())" @logo-click="run(()=>showEventList())" @search="s.eventSearch=$event;run(()=>showEventList())" />
<div class="flex min-h-0 flex-1"><MSidebar :items="nav.filter(n=>n.key!=='nhat-ky'||canAdmin)" :model-value="s.route" v-model:collapsed="sidebarCollapsed" @update:model-value="run(()=>navigate($event))"/><div class="flex min-w-0 min-h-0 flex-1 flex-col">
<div class="toolbar shrink-0 bg-[var(--mds-bg)] px-4 py-2"><MButton variant="secondary" @click="run(()=>showEventList())">Danh sách sự kiện</MButton><div class="w-96 max-w-full"><MCombobox :model-value="s.event?.id" :options="s.events.map(e=>({value:e.id,label:e.name}))" placeholder="Chọn sự kiện" @update:model-value="run(()=>selectEvent($event))"/></div><span>{{roleNames[s.event?.role]}}</span><MButton v-if="isSuper" variant="secondary" @click="s.dialog='new-event'">Tạo sự kiện</MButton></div>
<div class="toolbar px-4 py-3 shrink-0"><h1>{{title}}</h1><div v-if="s.route==='tong-quan'&&s.event" class="row"><MButton variant="secondary" :disabled="s.reportBusy||!s.report" :loading="s.busy" @click="run(exportExcel)">Xuất Excel</MButton><MButton variant="secondary" :disabled="s.reportBusy||!s.report" :loading="s.busy" @click="run(exportPng)">Xuất ảnh</MButton><MButton variant="primary" v-if="canEdit" @click="run(()=>navigate('nguon-du-lieu'))">Nhập dữ liệu</MButton></div></div>
<main class="scroll-region page-body stack"><div v-if="s.error" role="alert" class="error">{{s.error}}</div><div v-if="s.message" role="status" class="notice">{{s.message}}</div><progress v-if="s.busy" aria-label="Đang xử lý"/><MEmptyState v-if="!s.event" type="initial" title="Chọn hoặc tạo sự kiện để bắt đầu"/>
<template v-else-if="s.route==='tong-quan'"><ReportFilters/><div class="toolbar"><MTabs :model-value="s.table?'table':'chart'" :tabs="[{key:'chart',label:'Dashboard'},{key:'table',label:'Bảng số liệu'}]" @update:model-value="s.table=$event==='table'"/><MCheckbox v-model="s.showPercent" label="Hiển thị % trên biểu đồ"/></div><div class="row"><MCheckbox v-for="r in reports" :key="r.value" v-model="s.selected" :label="r.label" :value="r.value"/></div><div v-if="s.reportBusy" role="status" class="card row"><MSpinner/>Đang cập nhật số liệu theo bộ lọc…</div>
<div v-else-if="s.report" data-report class="stack"><ReportStamp/><div class="grid grid-cols-4 gap-4"><KpiCard v-for="kind in ['total','completion','clevel','ratio']" :key="kind" :kind="kind"/></div><p v-if="s.report.current.targetSum!==s.report.current.target" class="notice">Mục tiêu chi tiết cộng thành {{number(s.report.current.targetSum)}}, khác tổng mục tiêu sự kiện {{number(s.report.current.target)}}. Tỷ lệ toàn sự kiện dùng tổng mục tiêu.</p><ChartPanel title="Tình hình theo hình thức tham dự" :rows="s.report.current.modes" :table="s.table"/>
<div class="grid grid-cols-2 gap-4"><ChartPanel v-if="s.selected.includes('positions')" title="Cơ cấu chức vụ" :rows="s.report.current.positions" :table="s.table" pie/><ChartPanel v-if="s.selected.includes('sizes')" title="Quy mô doanh nghiệp" :rows="s.report.current.sizes" :table="s.table"/></div><ChartPanel v-if="s.selected.includes('trend')" title="Xu hướng đăng ký" :rows="s.report.current.trend.map(r=>({...r,label:dateText(r.label),percent:s.report.current.total?r.count/s.report.current.total*100:0}))" :table="s.table"/>
<template v-if="s.selected.includes('sources')"><label class="field">Chiều nguồn khách<MCombobox v-model="s.dimension" :options="s.report.sourceDimensions.map(d=>({value:d.name,label:d.name}))"/></label><ChartPanel :title="s.dimension||'Nguồn khách'" :rows="s.report.current.sourceBreakdowns.find(d=>d.name===s.dimension)?.values||[]" :table="s.table"/></template><TargetsPanel v-if="s.selected.includes('targets')"/>
<section class="card stack"><div class="toolbar"><h3>Nhận xét từ Gemini</h3><MButton variant="secondary" :loading="s.busy" @click="run(insights)">Phân tích số liệu</MButton></div><template v-if="s.insight"><p>{{s.insight.summary}}</p><p v-for="o in s.insight.observations" :key="o">{{o}}</p></template></section></div></template>
<template v-else-if="s.route==='thanh-vien'"><MemberImport/><div class="card"><MDataTable :rows="s.members" :columns="memberColumns" :total="s.members.length" :page-size="s.members.length||20"><template #cell-role="{row}"><MSelect v-if="isSuper" :model-value="row.role" :options="[{value:'editor',label:'Editor'},{value:'admin',label:'Admin'}]" @update:model-value="run(()=>setRole(row,$event))"/><span v-else>{{roleNames[row.role]}}</span></template><template #cell-actions="{row}"><MButton v-if="isSuper||(canAdmin&&row.role==='editor')" variant="link" @click="s.editMember=row;s.dialog='remove-member'">Thu hồi quyền</MButton></template></MDataTable></div></template>
<template v-else-if="s.route==='du-lieu'"><div class="row"><MInput v-model="s.query" placeholder="Tìm tên, email, công ty, tracking" @keyup.enter="run(loadRows)"/><MButton variant="secondary" @click="s.page=1;run(loadRows)">Tìm kiếm</MButton></div><div class="card"><MDataTable :columns="rowColumns" :rows="s.rows" :page="s.page" :page-size="50" :page-size-options="[50]" :total="s.rowTotal" :has-next="s.page*50<s.rowTotal" @update:page="s.page=$event;run(loadRows)"><template #cell-submitted_at="{row}">{{dateText(row.submitted_at)}}</template><template #cell-attendance_mode="{row}">{{({online:'Online',offline:'Offline',both:'Cả hai'})[row.attendance_mode]||'Chưa xác định'}}</template><template #cell-actions="{row}"><MButton v-if="canEdit" variant="link" @click="editRow(row)">Chỉnh sửa</MButton></template></MDataTable></div></template>
<ImportFields v-else-if="s.route==='nguon-du-lieu'"/><SettingsFields v-else-if="s.route==='muc-tieu'"/><section v-else-if="s.route==='nhat-ky'" class="card"><p v-if="!canAdmin">Bạn không có quyền xem nhật ký.</p><div v-else class="mobile-list"><article v-for="(a,i) in s.audit" :key="i">{{dateText(a.created_at)}} · {{a.name}} · {{a.action}}</article></div></section></main>
<footer v-if="s.route==='muc-tieu'&&canEdit" class="sticky-actions"><MButton variant="secondary" @click="run(()=>selectEvent(s.event.id))">Hủy thay đổi</MButton><MButton variant="primary" :loading="s.busy" @click="run(saveEvent)">Lưu thiết lập</MButton></footer></div></div></div></template>
